def build(force=False):
    if not os.path.exists(BETAS_C) and os.path.exists(GEN) and not force:  # [v12-package] SMDR sources optional:
        with open(GEN, encoding="utf-8") as f:  # use the shipped generated module, report its source hash
            return re.search(r"sha256=([0-9a-f]{64})", f.read(600)).group(1)
    src = open(BETAS_C, encoding="utf-8", errors="replace").read()
    h = hashlib.sha256(src.encode("utf-8")).hexdigest()
    if os.path.exists(GEN) and not force:
        with open(GEN, encoding="utf-8") as f:
            if h in f.read(400):
                return h
    txt = re.sub(r"/\*.*?\*/", " ", src, flags=re.S)
    body = txt[txt.index("int SMDR_Betas"):]
    want = set(AUX) | {n for v in ORD.values() for n in v if n}
    ex = {}
    for m in re.finditer(r"\b([A-Za-z_]\w*)\s*=\s*([^;=]+);", body):
        n, e = m.group(1), m.group(2)
        if n in want and n not in ex:
            e = " ".join(e.split())
            assert re.fullmatch(r"[\w\s\.\*\+\-/\(\)]+", e), (n, e[:80])
            ex[n] = e
    missing = want - set(ex)
    assert not missing, missing
    L = ["# -*- coding: utf-8 -*-",
         "# GENERATED by sm_rge.build() from SMDR-1.3/src/betas.c sha256=%s" % h,
         "# (C148 sm-mapping, 2026-10-14). Do not edit. Q dX/dQ = sum_n kappa^n betaX_n; kappa = 1/(16 pi^2).",
         "Zeta3 = 1.2020569031595942", "K = 1.0 / (16 * 3.141592653589793 ** 2)", "",
         "def orders(g3, g, gp, yt, yb, ytau, k, nmax=5):",
         "    g2 = g * g; g4 = g2 * g2; g6 = g4 * g2; g8 = g4 * g4",
         "    g32 = g3 * g3; g34 = g32 * g32; g36 = g34 * g32; g38 = g34 * g34",
         "    gp2 = gp * gp; gp4 = gp2 * gp2; gp6 = gp4 * gp2; gp8 = gp4 * gp4",
         "    yt2 = yt * yt; yt4 = yt2 * yt2; yt6 = yt4 * yt2; yt8 = yt4 * yt4",
         "    yb2 = yb * yb; yb4 = yb2 * yb2; yb6 = yb4 * yb2; yb8 = yb4 * yb4",
         "    ytau2 = ytau * ytau; ytau4 = ytau2 * ytau2; ytau6 = ytau4 * ytau2; ytau8 = ytau4 * ytau4",
         "    k2 = k * k; k3 = k2 * k; k4 = k2 * k2",
         "    yc = ys = yu = yd = ymu = ye = 0.0",
         "    out = []"]
    for a in AUX:
        L.append("    %s = %s" % (a, ex[a]))
    for n in range(1, 6):
        ind = "    " if n == 1 else "        "
        if n > 1:
            L.append("    if nmax >= %d:" % n)
        for nm in ORD[n]:
            if nm:
                L.append(ind + "%s = %s" % (nm, ex[nm]))
        fac = "K" if n == 1 else "K ** %d" % n
        L.append(ind + "out.append((" + ", ".join(("%s * %s" % (fac, nm)) if nm else "0.0" for nm in ORD[n]) + "))")
    L.append("    return out")
    with open(GEN + ".tmp", "w", encoding="utf-8") as f:
        f.write("\n".join(L) + "\n")
    os.replace(GEN + ".tmp", GEN)
    return h


