import _smdr_betas as SB  # noqa: E402


def smdr_orders(y, nmax=5):
    g3, g, gp, yt, yb, ytau, k = y[:7]
    return SB.orders(g3, g, gp, yt, yb, ytau, k, nmax)


def rhs_smdr(loops=5):
    def f(t, y):
        o = SB.orders(y[0], y[1], y[2], y[3], y[4], y[5], y[6], loops)
        s = [sum(c[i] for c in o) for i in range(8)]
        return [s[0], s[1], s[2], s[3], s[4], s[5], s[6], -y[7] * s[7]]
    return f


# ------------------------------------------------------------------------------------------------ (B) Buttazzo
def b13_orders(y, nmax=4):
    """Buttazzo App. B (d/dln mu^2 of g1^2, g2^2, g3^2, yt^2, lambda; yb = ytau = 0) -> dX/dln mu, SMDR layout."""
    g3, g, gp, yt, _, _, l = y[:7]
    a1, a2, a3, t = 5.0 / 3 * gp * gp, g * g, g3 * g3, yt * yt
    L = K
    G1 = [a1 * a1 * L * 41 / 10,
          a1 * a1 * L ** 2 * (44 * a3 / 5 + 27 * a2 / 10 + 199 * a1 / 50 - 17 * t / 10),
          a1 * a1 * L ** 3 * (t * (189 * t / 16 - 29 * a3 / 5 - 471 * a2 / 32 - 2827 * a1 / 800)
                              + l * (-9 * l / 5 + 9 * a2 / 10 + 27 * a1 / 50) + 297 * a3 ** 2 / 5 + 789 * a2 ** 2 / 64
                              - 388613 * a1 ** 2 / 24000 - 3 * a3 * a2 / 5 - 137 * a3 * a1 / 75 + 123 * a2 * a1 / 160),
          0.0]
    G2 = [a2 * a2 * L * (-19.0 / 6),
          a2 * a2 * L ** 2 * (12 * a3 + 35 * a2 / 6 + 9 * a1 / 10 - 3 * t / 2),
          a2 * a2 * L ** 3 * (t * (147 * t / 16 - 7 * a3 - 729 * a2 / 32 - 593 * a1 / 160)
                              + l * (-3 * l + 3 * a2 / 2 + 3 * a1 / 10) + 81 * a3 ** 2 + 324953 * a2 ** 2 / 1728
                              - 5597 * a1 ** 2 / 1600 + 39 * a3 * a2 - a3 * a1 / 5 + 873 * a2 * a1 / 160),
          0.0]
    G3 = [a3 * a3 * L * (-7.0),
          a3 * a3 * L ** 2 * (-26 * a3 + 9 * a2 / 2 + 11 * a1 / 10 - 2 * t),
          a3 * a3 * L ** 3 * (t * (15 * t - 40 * a3 - 93 * a2 / 8 - 101 * a1 / 40) + 65 * a3 ** 2 / 2
                              + 109 * a2 ** 2 / 8 - 523 * a1 ** 2 / 120 + 21 * a3 * a2 + 77 * a3 * a1 / 15
                              - 3 * a2 * a1 / 40),
          a3 ** 5 * L ** 4 * (-2472.28)]
    LA = [L * (l * (12 * l + 6 * t - 9 * a2 / 2 - 9 * a1 / 10) - 3 * t * t + 9 * a2 ** 2 / 16 + 27 * a1 ** 2 / 400
               + 9 * a2 * a1 / 40),
          L ** 2 * (l * l * (-156 * l - 72 * t + 54 * a2 + 54 * a1 / 5)
                    + l * t * (-3 * t / 2 + 40 * a3 + 45 * a2 / 4 + 17 * a1 / 4)
                    + l * (-73 * a2 ** 2 / 16 + 1887 * a1 ** 2 / 400 + 117 * a2 * a1 / 40)
                    + t * t * (15 * t - 16 * a3 - 4 * a1 / 5)
                    + t * (-9 * a2 ** 2 / 8 - 171 * a1 ** 2 / 200 + 63 * a2 * a1 / 20)
                    + 305 * a2 ** 3 / 32 - 3411 * a1 ** 3 / 4000 - 289 * a2 ** 2 * a1 / 160
                    - 1677 * a2 * a1 ** 2 / 800),
          L ** 3 * (l ** 3 * (6011.35 * l + 873 * t - 387.452 * a2 - 77.490 * a1)
                    + l * l * t * (1768.26 * t + 160.77 * a3 - 359.539 * a2 - 63.869 * a1)
                    + l * l * (-790.28 * a2 ** 2 - 185.532 * a1 ** 2 - 316.64 * a2 * a1)
                    + l * t * t * (-223.382 * t - 662.866 * a3 - 5.470 * a2 - 21.015 * a1)
                    + l * t * (356.968 * a3 ** 2 - 319.664 * a2 ** 2 - 74.8599 * a1 ** 2 + 15.1443 * a3 * a2
                               + 17.454 * a3 * a1 + 5.615 * a2 * a1)
                    + l * a2 ** 2 * (-57.144 * a3 + 865.483 * a2 + 79.638 * a1)
                    + l * a1 ** 2 * (-8.381 * a3 + 61.753 * a2 + 28.168 * a1)
                    + t ** 3 * (-243.149 * t + 250.494 * a3 + 74.138 * a2 + 33.930 * a1)
                    + t * t * (-50.201 * a3 ** 2 + 15.884 * a2 ** 2 + 15.948 * a1 ** 2 + 13.349 * a3 * a2
                               + 17.570 * a3 * a1 - 70.356 * a2 * a1)
                    + t * a3 * (16.464 * a2 ** 2 + 1.016 * a1 ** 2 + 11.386 * a2 * a1)
                    + t * a2 ** 2 * (62.500 * a2 + 13.041 * a1)
                    + t * a1 ** 2 * (10.627 * a2 + 11.117 * a1)
                    + a3 * (7.536 * a2 ** 3 + 0.663 * a1 ** 3 + 1.507 * a2 ** 2 * a1 + 1.105 * a2 * a1 ** 2)
                    - 114.091 * a2 ** 4 - 1.508 * a1 ** 4 - 37.889 * a2 ** 3 * a1 + 6.500 * a2 ** 2 * a1 ** 2
                    - 1.543 * a2 * a1 ** 3),
          0.0]
    YT = [t * L * (9 * t / 2 - 8 * a3 - 9 * a2 / 4 - 17 * a1 / 20),
          t * L ** 2 * (t * (-12 * t - 12 * l + 36 * a3 + 225 * a2 / 16 + 393 * a1 / 80) + 6 * l * l
                        - 108 * a3 ** 2 - 23 * a2 ** 2 / 4 + 1187 * a1 ** 2 / 600 + 9 * a3 * a2 + 19 * a3 * a1 / 15
                        - 9 * a2 * a1 / 20),
          t * L ** 3 * (t * t * (58.6028 * t + 198 * l - 157 * a3 - 1593 * a2 / 16 - 2437 * a1 / 80)
                        + l * t * (15 * l / 4 + 16 * a3 - 135 * a2 / 2 - 127 * a1 / 10)
                        + t * (363.764 * a3 ** 2 + 16.990 * a2 ** 2 - 24.422 * a1 ** 2 + 48.370 * a3 * a2
                               + 18.074 * a3 * a1 + 34.829 * a2 * a1)
                        + l * l * (-36 * l + 45 * a2 + 9 * a1) + l * (-171 * a2 ** 2 / 16 - 1089 * a1 ** 2 / 400
                                                                       + 117 * a2 * a1 / 40)
                        - 619.35 * a3 ** 3 + 169.829 * a2 ** 3 + 16.099 * a1 ** 3 + 73.654 * a3 ** 2 * a2
                        - 15.096 * a3 ** 2 * a1 - 21.072 * a3 * a2 ** 2 - 22.319 * a3 * a1 ** 2
                        - 321.0 / 20 * a3 * a2 * a1 - 4.743 * a2 ** 2 * a1 - 4.442 * a2 * a1 ** 2),
          0.0]
    out = []
    for n in range(min(nmax, 4)):
        out.append((G3[n] / g3, G2[n] / g, 0.6 * G1[n] / gp, YT[n] / yt, 0.0, 0.0, 2 * LA[n], 0.0))
    return out


def rhs_b13(loops=3):
    def f(t, y):
        o = b13_orders(y, loops)
        s = [sum(c[i] for c in o) for i in range(8)]
        return [s[0], s[1], s[2], s[3], 0.0, 0.0, s[6], 0.0]
    return f


def solve(y0, mu0, mu1, loops=5, impl="smdr", dense=True, rtol=1e-11, mu_eval=None):
    f = rhs_smdr(loops) if impl == "smdr" else rhs_b13(min(loops, 4))
    te = None if mu_eval is None else np.log(np.atleast_1d(mu_eval))
    return solve_ivp(f, (math.log(mu0), math.log(mu1)), list(y0), method="DOP853", rtol=rtol, atol=1e-15,
                     dense_output=dense, t_eval=te)


# pure-QCD parts (for the matching-scale reconstruction): b = d ln X/d ln mu, X = yt or g3
def bqcd_yt(g3, nmax=5):
    a = g3 * g3 * K
    c = [-8.0, -108.0, -4166.0 / 3 + 640 * ZETA3, 2308.18, 19988.8]
    return sum(c[n] * a ** (n + 1) for n in range(nmax))


def bqcd_g3(g3, nmax=5):
    a = g3 * g3 * K
    c = [-7.0, -26.0, 65.0 / 2, 63559.0 / 18 - 44948.0 * ZETA3 / 9, -271.428]
    return sum(c[n] * a ** (n + 1) for n in range(nmax))
